function parseUri(s){
  var u=String(s||'');
  var m=/^([a-zA-Z][a-zA-Z0-9+.\-]*):\/\/([^\/?#]*)([^?#]*)(\?[^#]*)?(#.*)?$/.exec(u);
  if(!m) return {ok:false, reason:'not an absolute URI'};
  var qs=(m[4]||'').replace(/^\?/,'');
  var params={};
  if(qs){ var parts=qs.split('&');
    for(var i=0;i<parts.length;i++){ if(!parts[i]) continue;
      var kv=parts[i].split('=');
      var k=decodeURIComponent(kv[0]||'');
      var v=decodeURIComponent((kv[1]||'').replace(/\+/g,' '));
      params[k]=v;
    } }
  return {ok:true, scheme:m[1], host:m[2], path:m[3]||'/', query:qs, fragment:(m[5]||'').replace(/^#/,''), params:params};
}
function encodeUri(s){ return encodeURIComponent(String(s||'')); }
function decodeUri(s){ try { return decodeURIComponent(String(s||'').replace(/\+/g,' ')); } catch(e){ return ''; } }

var EXPORTS={parseUri:parseUri,encodeUri:encodeUri,decodeUri:decodeUri};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.UriForgePure = EXPORTS; }
